<script lang="ts">
 import {app} from '#lib/state.svelte.ts';
 import type {MarketGroup} from '#lib/engine/market_book.js';
 import {odds,pct,signed} from '#lib/format.ts';
 import SelectionIdentity from './SelectionIdentity.svelte';
 let {groups,valueOnly=false,home='',away=''}:{groups:MarketGroup[];valueOnly?:boolean;home?:string;away?:string}=$props();
 let feedback=$state('');
 const shown=$derived(groups.map(g=>({...g,selections:[...(valueOnly?g.selections.filter(s=>(s as any).opportunity?.green):g.selections)].sort((a,b)=>b.modelProb-a.modelProb||a.id.localeCompare(b.id))})).filter(g=>g.selections.length));
</script>
{#if !shown.length}<p class="surface p-4 text-sm text-haze">No choices match this market filter.</p>{/if}
<div class="market-groups">
 {#each shown as g(g.key)}<details class="market-accordion"><summary class="market-summary"><span class="min-w-0"><strong><span aria-hidden="true">{g.emoji}</span> {g.title}</strong><small>{g.selections.length} options · Model % high to low</small></span><span class="accordion-chevron" aria-hidden="true">⌄</span></summary>
 <p class="px-3 pb-3 text-xs text-haze">{g.blurb}</p>
 <ul class="market-tiles">{#each g.selections as s(s.id)}
 {@const inSlip=app.inSlip(s.id)}{@const selectable=app.gameById(s.fixtureId)?.status.state==='scheduled'&&Date.parse(app.gameById(s.fixtureId)?.kickoff??'')>app.now}{@const opportunity=(s as any).opportunity}
 <li class:selected={inSlip}>
 <div class="market-choice">
 <span class="choice-name">{#if opportunity?.green}<span class="choice-light" aria-hidden="true"></span>{/if}<SelectionIdentity selection={s} {home} {away}/></span>
 <span class="choice-prob">{pct(s.modelProb,1)}<small>Model</small></span>
 <span class="choice-meta">Projection {(s as any).projectionGrade??'—'} · {s.pricing==='quoted'?s.bookmaker:'Fair estimate'}<span class="choice-price">{odds(s.pricing==='quoted'?s.bestOdds:s.fairOdds)}</span></span>
 <button class="choice-add" disabled={!selectable&&!inSlip} aria-pressed={inSlip} aria-label={inSlip?`Remove ${s.selection} from betslip`:selectable?`Add ${s.selection} to betslip`:`Cannot add ${s.selection}: pre-match selection closed`} title={inSlip?'Remove from betslip':selectable?'Add to betslip':'Pre-match selection closed'} onclick={()=>{app.toggle(s);feedback=app.inSlip(s.id)?`${s.selection} added to betslip.`:`${s.selection} removed from betslip.`;}}><span aria-hidden="true">{inSlip?'✓':'+'}</span></button>
 {#if !selectable&&!inSlip}<span class="choice-unavailable">Pre-match selection closed</span>{/if}
 </div>
 <details class="choice-note"><summary>Analysis <span>{s.pricing==='quoted'?`${signed(s.edgePercent,1)}% EV`:'Quote unavailable'}{#if s.pushProb>.005} · {pct(s.pushProb)} refund{/if}</span></summary><div><p>{opportunity?.note??'No market choice note is available.'}</p><p class="mt-2">{opportunity?.gradeBasis??'Model probabilities are estimates, not measured accuracy.'}</p><p class="mt-2">Fair price {odds(s.fairOdds)}. {s.pricing==='quoted'?`Value grade ${s.grade}. Confirm current bookmaker price.`:'Add this unpriced selection to your slip. Its fair estimate is excluded from quoted combined odds.'}</p></div></details>
 </li>{/each}</ul></details>{/each}
</div>
<p class="sr-only" role="status" aria-live="polite">{feedback}</p>
<style>
 .market-groups{display:grid;min-width:0;gap:12px;grid-template-columns:minmax(0,1fr)}.market-accordion{min-width:0;max-width:100%;border:1px solid var(--color-line);border-radius:16px;background:var(--color-deep);overflow:hidden}.market-summary{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:14px;min-height:58px;cursor:pointer;list-style:none}.market-summary::-webkit-details-marker{display:none}.market-summary strong{font-size:14px;overflow-wrap:anywhere}.market-summary small{display:block;margin-top:3px;font-size:11px;color:var(--color-haze)}.accordion-chevron{flex-shrink:0;font-size:22px}.market-accordion[open] .accordion-chevron{transform:rotate(180deg)}.market-tiles{display:grid;grid-template-columns:minmax(0,1fr);gap:8px;padding:0 10px 10px}.market-tiles li{min-width:0;border:1px solid var(--color-line);border-radius:12px;background:var(--color-ink);overflow:hidden}.market-tiles li.selected{border-color:var(--color-model);background:var(--color-raised)}.market-choice{display:grid;width:100%;grid-template-columns:minmax(0,1fr) 58px 44px;gap:5px 8px;align-items:center;padding:10px 12px;text-align:left;min-height:74px}.market-choice:has(.choice-add:not(:disabled)):hover{background:var(--color-raised)}.choice-name{font-size:14px;font-weight:650;line-height:1.35;overflow-wrap:anywhere}.choice-light{display:inline-block;width:8px;height:8px;border-radius:50%;background:#34d399;margin-right:6px}.choice-prob{text-align:right;font-size:17px;line-height:1.15;font-weight:700;color:var(--color-model);grid-column:2;grid-row:1/3}.choice-prob small{display:block;font-size:10px;font-weight:500;color:var(--color-haze);margin-top:3px}.choice-meta{grid-column:1;min-width:0;font-size:11px;color:var(--color-haze);overflow-wrap:anywhere}.choice-price{margin-left:8px;font-weight:700;color:var(--color-book)}.choice-add{display:grid;place-items:center;width:44px;min-height:44px;grid-column:3;grid-row:1/3;border-radius:10px;background:#10b98126;border:1px solid #34d39988;font-size:24px;font-weight:700;color:var(--color-model);cursor:pointer}.choice-add:hover:not(:disabled){background:#10b98155}.choice-add:focus-visible{outline:2px solid var(--color-model);outline-offset:2px}.choice-add:disabled{color:var(--color-haze);border-color:var(--color-line);background:var(--color-raised);cursor:not-allowed}.choice-unavailable{grid-column:1/-1;color:var(--color-haze);font-size:10px}.choice-note{border-top:1px solid var(--color-line);font-size:11px;color:var(--color-haze)}.choice-note summary{display:flex;flex-wrap:wrap;justify-content:space-between;gap:4px;padding:7px 12px;cursor:pointer;min-height:32px}.choice-note div{padding:4px 12px 12px;line-height:1.6;overflow-wrap:anywhere}
</style>
